using MyProjectManagement;
using System.Text.Json.Nodes;
public static class PointReviewTests {
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}static void Deny(Action action){try{action();}catch(ApiError){return;}throw new Exception("Expected point review validation denial");}
 public static void Run(){var bytes=File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory,"Fixtures/CR-Format-Synthetic.docx"));var map=ChangeRequestWord.Read(bytes);var points=map["points"]!.AsArray();points[0]!["serial"]="007";points[1]!["serial"]="A.2";
 var row=new JsonObject{["revisions"]=new JsonArray()};var rev=new JsonObject{["number"]=1};row["revisions"]!.AsArray().Add(rev);StructuredChangeRequest.Fields(row,rev,new JsonObject{["header"]=map["header"]!.DeepClone(),["points"]=points.DeepClone()});var saved=rev["points"]!.AsArray();Check(J.S(saved[0],"serial")=="007"&&J.S(saved[1],"serial")=="A.2","Serials preserved in database fields");var output=ChangeRequestWord.Rewrite(bytes,rev["header"]!.AsObject(),saved);var read=ChangeRequestWord.Read(output,saved);Check(J.S(read["points"]![0],"serial")=="007"&&J.S(read["points"]![1],"serial")=="A.2","Serials preserved through synchronized Word output");
 JsonObject Body(string status="Proceed",string remarks="")=>new(){["pointDecisions"]=new JsonArray(saved.OfType<JsonObject>().Select(p=>(JsonNode)new JsonObject{["point"]=J.S(p,"id"),["status"]=status,["remarks"]=remarks}).ToArray())};
 Deny(()=>PointReviews.Capture(rev,new JsonObject(),"Approve",new JsonArray()));var b=Body();b["pointDecisions"]!.AsArray().RemoveAt(1);Deny(()=>PointReviews.Capture(rev,b,"Approve",new JsonArray()));b=Body();b["pointDecisions"]![1]!["point"]=J.S(saved[0],"id");Deny(()=>PointReviews.Capture(rev,b,"Approve",new JsonArray()));Deny(()=>PointReviews.Capture(rev,Body("Revision required"),"Amendment",new JsonArray()));Deny(()=>PointReviews.Capture(rev,Body("Revision required","Clarify this"),"Approve",new JsonArray()));
 b=Body();b["pointDecisions"]![0]!["status"]="Revision required";b["pointDecisions"]![0]!["remarks"]="Change posting";b["pointDecisions"]![1]!["remarks"]="This can proceed";var notes=new JsonArray();var decisions=PointReviews.Capture(rev,b,"Amendment",notes);Check(decisions.Count==2&&J.S(decisions[0],"serial")=="007"&&J.S(notes[0],"pointStatus")=="Revision required","Independent point status/serial and comments captured");rev["reviews"]=new JsonArray(new JsonObject{["by"]="pm",["stage"]="PM",["decision"]="Amendment",["comments"]=notes,["pointDecisions"]=decisions});
 var next=new JsonObject{["number"]=2,["header"]=rev["header"]!.DeepClone(),["points"]=saved.DeepClone(),["amendmentResponses"]=new JsonArray()};row["revisions"]!.AsArray().Add(next);Deny(()=>StructuredChangeRequest.Submit(row));var required=StructuredChangeRequest.PriorNotes(row).Where(n=>J.S(n,"pointStatus")=="Revision required");next["amendmentResponses"]=new JsonArray(required.Select(n=>(JsonNode)new JsonObject{["key"]=J.S(n,"key"),["reply"]="Changed as requested"}).ToArray());StructuredChangeRequest.Submit(row);Check(StructuredChangeRequest.PriorNotes(row).Count==2,"Proceed remarks retained without requiring unnecessary amendment response");
 Console.WriteLine("PASS v52: imported serials through fields/Word round trip, complete and unique point decisions, required revision remarks, blocked contradictory approval and targeted amendment responses.");}
}
